CREATE OR REPLACE FUNCTION public.broker_can_review(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.hercules_has_any_role(auth.uid(),ARRAY['broker','dispatcher']::public.hercules_role[]) AND EXISTS(SELECT 1 FROM public.company_members WHERE company_id=_company AND user_id=auth.uid() AND status='active') $$;
CREATE TABLE public.broker_driver_recipients(company_id uuid NOT NULL, user_id uuid NOT NULL, carrier_id uuid NOT NULL, display_name text NOT NULL, recipient_email text NOT NULL, verified_at timestamptz NOT NULL, PRIMARY KEY(company_id,user_id), FOREIGN KEY(company_id,user_id) REFERENCES public.company_members(company_id,user_id), FOREIGN KEY(company_id,carrier_id) REFERENCES public.freight_carriers(company_id,id));
GRANT SELECT ON public.broker_driver_recipients TO authenticated; GRANT ALL ON public.broker_driver_recipients TO service_role;
ALTER TABLE public.broker_driver_recipients ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviewer_driver_read ON public.broker_driver_recipients FOR SELECT TO authenticated USING(public.broker_can_review(company_id) OR user_id=auth.uid());
COMMENT ON TABLE public.broker_driver_recipients IS 'Trusted verified driver/carrier mapping only. No client write or invented recipient verification.';
CREATE TABLE public.broker_load_releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, draft_id uuid NOT NULL UNIQUE, outbox_id uuid NOT NULL UNIQUE REFERENCES public.broker_delivery_outbox(id), driver_id uuid NOT NULL, carrier_id uuid NOT NULL, driver_email text NOT NULL, release_at timestamptz NOT NULL, time_zone text NOT NULL, pickup_at timestamptz NOT NULL, delivery_at timestamptz NOT NULL, priority integer NOT NULL DEFAULT 0 CHECK(priority BETWEEN 0 AND 100), cancelled_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,draft_id) REFERENCES public.broker_intake_drafts(company_id,id), FOREIGN KEY(company_id,driver_id) REFERENCES public.broker_driver_recipients(company_id,user_id), FOREIGN KEY(company_id,carrier_id) REFERENCES public.freight_carriers(company_id,id));
GRANT SELECT ON public.broker_load_releases TO authenticated; GRANT ALL ON public.broker_load_releases TO service_role;
ALTER TABLE public.broker_load_releases ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviewer_release_read ON public.broker_load_releases FOR SELECT TO authenticated USING(public.broker_can_review(company_id) OR (driver_id=auth.uid() AND EXISTS(SELECT 1 FROM public.company_members m WHERE m.company_id=broker_load_releases.company_id AND m.user_id=auth.uid() AND m.status='active')));
CREATE INDEX broker_driver_release_order ON public.broker_load_releases(company_id,driver_id,pickup_at) WHERE cancelled_at IS NULL;
CREATE OR REPLACE FUNCTION public.broker_release_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.time_zone) OR NEW.delivery_at<=NEW.pickup_at OR NEW.release_at>NEW.pickup_at THEN RAISE EXCEPTION 'Valid timezone and ordered release/pickup/delivery times required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.broker_delivery_outbox o WHERE o.id=NEW.outbox_id AND o.company_id=NEW.company_id AND o.draft_id=NEW.draft_id AND o.carrier_id=NEW.carrier_id) THEN RAISE EXCEPTION 'Approved matching outbox required'; END IF; IF TG_OP='UPDATE' AND (NEW.company_id,NEW.draft_id,NEW.outbox_id,NEW.driver_id,NEW.carrier_id,NEW.driver_email) IS DISTINCT FROM (OLD.company_id,OLD.draft_id,OLD.outbox_id,OLD.driver_id,OLD.carrier_id,OLD.driver_email) THEN RAISE EXCEPTION 'Approved assignment immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER broker_release_guard BEFORE INSERT OR UPDATE ON public.broker_load_releases FOR EACH ROW EXECUTE FUNCTION public.broker_release_validate();
CREATE OR REPLACE FUNCTION public.broker_review_batch(_company uuid,_items jsonb,_confirmed boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; recipient public.broker_driver_recipients; existing public.broker_load_releases; job uuid; ids jsonb='[]'::jsonb; pickup timestamptz; finish timestamptz; release_time timestamptz; zone text; pri integer; BEGIN IF _confirmed IS NOT TRUE OR NOT public.broker_can_review(_company) THEN RAISE EXCEPTION 'Explicit reviewer approval and active company required'; END IF; IF jsonb_typeof(_items)<>'array' OR jsonb_array_length(_items) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Choose 1 to 50 itemized loads'; END IF; IF (SELECT count(DISTINCT x->>'draftId') FROM jsonb_array_elements(_items) x)<>jsonb_array_length(_items) THEN RAISE EXCEPTION 'Duplicate load in batch'; END IF; PERFORM 1 FROM public.companies WHERE id=_company FOR UPDATE; FOR item IN SELECT value FROM jsonb_array_elements(_items) LOOP IF NOT EXISTS(SELECT 1 FROM public.broker_intake_drafts WHERE id=(item->>'draftId')::uuid AND company_id=_company) THEN RAISE EXCEPTION 'Load company mismatch'; END IF; pickup=(item->>'pickupAt')::timestamptz; finish=(item->>'deliveryAt')::timestamptz; release_time=coalesce((item->>'releaseAt')::timestamptz,now()); zone=item->>'timeZone'; pri=(item->>'priority')::integer; IF pickup IS NULL OR finish IS NULL OR zone IS NULL OR pri IS NULL OR pri NOT BETWEEN 0 AND 100 OR finish<=pickup OR release_time>pickup OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN RAISE EXCEPTION 'Invalid times, timezone or priority'; END IF; SELECT * INTO existing FROM public.broker_load_releases WHERE draft_id=(item->>'draftId')::uuid; IF existing.id IS NOT NULL THEN IF existing.driver_id=(item->>'driverId')::uuid AND existing.carrier_id=(item->>'carrierId')::uuid AND existing.pickup_at=pickup AND existing.delivery_at=finish AND existing.priority=pri AND existing.time_zone=zone AND ((item->>'releaseAt') IS NULL OR existing.release_at=release_time) AND existing.cancelled_at IS NULL AND EXISTS(SELECT 1 FROM public.broker_delivery_outbox WHERE id=existing.outbox_id AND packet->>'document_id'=item->>'documentId' AND approved_by=auth.uid()) THEN ids=ids||jsonb_build_array(existing.id); CONTINUE; END IF; RAISE EXCEPTION 'Existing approval differs; use cancel/reschedule'; END IF; IF pickup<=now() OR ((item->>'releaseAt') IS NOT NULL AND release_time<=now()) THEN RAISE EXCEPTION 'Future pickup and scheduled release required'; END IF; SELECT * INTO recipient FROM public.broker_driver_recipients WHERE company_id=_company AND user_id=(item->>'driverId')::uuid AND carrier_id=(item->>'carrierId')::uuid FOR SHARE; IF recipient.user_id IS NULL OR recipient.recipient_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR NOT EXISTS(SELECT 1 FROM public.company_members WHERE company_id=_company AND user_id=recipient.user_id AND status='active') OR NOT public.hercules_has_role(recipient.user_id,'driver') THEN RAISE EXCEPTION 'Active verified driver linked to carrier required'; END IF; IF EXISTS(SELECT 1 FROM public.broker_load_releases WHERE company_id=_company AND driver_id=recipient.user_id AND cancelled_at IS NULL AND tstzrange(pickup_at,delivery_at,'[)') && tstzrange(pickup,finish,'[)')) OR EXISTS(SELECT 1 FROM public.freight_loads WHERE company_id=_company AND driver_id=recipient.user_id AND status NOT IN ('delivered','closed','cancelled') AND (pickup_at IS NULL OR delivery_at IS NULL OR tstzrange(pickup_at,delivery_at,'[)') && tstzrange(pickup,finish,'[)'))) THEN RAISE EXCEPTION 'Driver schedule conflict or existing assignment missing times'; END IF; job=public.broker_intake_approve((item->>'draftId')::uuid,(item->>'carrierId')::uuid,(item->>'documentId')::uuid,true); INSERT INTO public.broker_load_releases(company_id,draft_id,outbox_id,driver_id,carrier_id,driver_email,release_at,time_zone,pickup_at,delivery_at,priority) VALUES(_company,(item->>'draftId')::uuid,job,recipient.user_id,recipient.carrier_id,recipient.recipient_email,release_time,zone,pickup,finish,pri) RETURNING * INTO existing; INSERT INTO public.broker_review_history(company_id,draft_id,actor_id,action,detail) VALUES(_company,existing.draft_id,auth.uid(),'approved_driver_release',jsonb_build_object('release_id',existing.id,'driver_id',recipient.user_id,'release_at',release_time,'time_zone',zone,'priority',pri)); ids=ids||jsonb_build_array(existing.id); END LOOP; RETURN ids; END $$;
REVOKE ALL ON FUNCTION public.broker_review_batch(uuid,jsonb,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.broker_review_batch(uuid,jsonb,boolean) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.broker_intake_approve(uuid,uuid,uuid,boolean) FROM authenticated;
CREATE OR REPLACE FUNCTION public.broker_release_change(_id uuid,_version integer,_cancel boolean,_release_at timestamptz,_zone text,_confirmed boolean) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.broker_load_releases; o public.broker_delivery_outbox; BEGIN SELECT * INTO r FROM public.broker_load_releases WHERE id=_id FOR UPDATE; IF r.id IS NULL OR _confirmed IS NOT TRUE OR NOT public.broker_can_review(r.company_id) THEN RAISE EXCEPTION 'Explicit reviewer confirmation required'; END IF; SELECT * INTO o FROM public.broker_delivery_outbox WHERE id=r.outbox_id FOR UPDATE; IF r.version<>_version OR r.cancelled_at IS NOT NULL OR o.status NOT IN ('needs_connection','pending','failed') OR o.locked_until>now() THEN RAISE EXCEPTION 'Stale, cancelled or in-flight release cannot change'; END IF; IF NOT _cancel AND (_release_at IS NULL OR _release_at<=now() OR _release_at>r.pickup_at OR _zone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=_zone)) THEN RAISE EXCEPTION 'Future release before pickup with valid timezone required'; END IF; UPDATE public.broker_load_releases SET cancelled_at=CASE WHEN _cancel THEN now() ELSE NULL END,release_at=CASE WHEN _cancel THEN release_at ELSE _release_at END,time_zone=CASE WHEN _cancel THEN time_zone ELSE _zone END,version=version+1 WHERE id=r.id; INSERT INTO public.broker_review_history(company_id,draft_id,actor_id,action,detail) VALUES(r.company_id,r.draft_id,auth.uid(),CASE WHEN _cancel THEN 'release_cancelled' ELSE 'release_rescheduled' END,jsonb_build_object('previous_release_at',r.release_at,'release_at',_release_at,'time_zone',_zone,'previous_version',r.version)); RETURN r.version+1; END $$;
REVOKE ALL ON FUNCTION public.broker_release_change(uuid,integer,boolean,timestamptz,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.broker_release_change(uuid,integer,boolean,timestamptz,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.broker_my_stack() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'reference',d.reference,'origin',d.origin,'destination',d.destination,'priority',r.priority,'pickupAt',r.pickup_at,'deliveryAt',r.delivery_at,'releaseAt',r.release_at,'timeZone',r.time_zone,'deliveryStatus',o.status) ORDER BY r.priority DESC,r.pickup_at,r.id),'[]'::jsonb) FROM public.broker_load_releases r JOIN public.broker_intake_drafts d ON d.id=r.draft_id JOIN public.broker_delivery_outbox o ON o.id=r.outbox_id WHERE r.driver_id=auth.uid() AND public.hercules_has_role(auth.uid(),'driver') AND r.cancelled_at IS NULL AND r.delivery_at>now() AND EXISTS(SELECT 1 FROM public.company_members m WHERE m.company_id=r.company_id AND m.user_id=auth.uid() AND m.status='active') $$;
REVOKE ALL ON FUNCTION public.broker_my_stack() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.broker_my_stack() TO authenticated;
CREATE POLICY reviewer_carriers_read ON public.freight_carriers FOR SELECT TO authenticated USING(public.broker_can_review(company_id));
COMMENT ON TABLE public.broker_load_releases IS 'Approved assignments and desired release times only; no scheduler or delivery provider activated. Worker must exclude cancelled rows, wait for release_at, enforce version/lease and reverify both recipients and immutable packet.';